//     0 -> 2 [ ]
//     0 -> 3 [ ]
//     1 -> 2 [ ]
//     1 -> 3 [ ]
//     2 -> 3 [ ]
// }

// If you need multiple config options, just list them all in the slice.
```

3431.docs:
Create a new `Graph` by mapping nodes and edges.
A node or edge may be mapped to `None` to exclude it from
the resulting graph.

Nodes are mapped first with the `node_map` closure, then
`edge_map` is called for the edges that have not had any endpoint
removed.

The resulting graph has the structure of a subgraph of the original graph.
If no nodes are removed, the resulting graph has compatible node
indices; if neither nodes nor edges are removed, the result has
the same graph indices as `self`.

If you want a consuming version of this function, see [`filter_map_owned`](struct.Graph.html#method.filter_map_owned).

```
use petgraph::Graph;

// Create a graph with integer node weights
let mut g = Graph::<u32, ()>::new();
let a = g.add_node(0);
let b = g.add_node(2);
let c = g.add_node(5);
let d = g.add_node(7);
let e = g.add_node(4);
g.extend_with_edges(&[(a, b, ()), (a, c, ()), (b, d, ()), (c, d, ()), (d, e, ())]);

// Filter the graph such that only nodes with weight greater than 2 are kept.
let g_filtered = g.filter_map(
    |_, &node_weight| if node_weight > 2 { Some(node_weight) } else { None },
    |_, &edge_weight| Some(edge_weight),
);

assert_eq!(g_filtered.node_count(), 3);
```

2523.docs:
[Graph] Condense every strongly connected component into a single node and return the result.

# Arguments
* `g`: an input [`Graph`].
* `make_acyclic`: if `true`, self-loops and multi edges are ignored, guaranteeing that
  the output is acyclic.

# Returns
Returns a `Graph` with nodes `Vec<N>` representing strongly connected components.

# Complexity
* Time complexity: **O(|V| + |E|)**.
* Auxiliary space: **O(|V| + |E|)**.

where **|V|** is the number of nodes and **|E|** is the number of edges.

# Examples
```rust
use petgraph::Graph;
use petgraph::algo::condensation;
use petgraph::prelude::*;

let mut graph : Graph<(),(),Directed> = Graph::new();
let a = graph.add_node(()); // node with no weight
let b = graph.add_node(());
let c = graph.add_node(());
let d = graph.add_node(());
let e = graph.add_node(());
let f = graph.add_node(());
let g = graph.add_node(());
let h = graph.add_node(());

graph.extend_with_edges(&[
    (a, b),
    (b, c),
    (c, d),
    (d, a),
    (b, e),
    (e, f),
    (f, g),
    (g, h),
    (h, e)
]);

// a ----> b ----> e ----> f
// ^       |       ^       |
// |       v       |       v
// d <---- c       h <---- g

let condensed_graph = condensation(graph,false);
let A = NodeIndex::new(0);
let B = NodeIndex::new(1);
assert_eq!(condensed_graph.node_count(), 2);
assert_eq!(condensed_graph.edge_count(), 9);
assert_eq!(condensed_graph.neighbors(A).collect::<Vec<_>>(), vec![A, A, A, A]);
assert_eq!(condensed_graph.neighbors(B).collect::<Vec<_>>(), vec![A, B, B, B, B]);
```
If `make_acyclic` is true, self-loops and multi edges are ignored:

```rust
# use petgraph::Graph;
# use petgraph::algo::condensation;
# use petgraph::prelude::*;
#
# let mut graph : Graph<(),(),Directed> = Graph::new();
# let a = graph.add_node(()); // node with no weight
# let b = graph.add_node(());
